import os
import requests
from typing import Optional, Dict, Any


class Auth0TokenRefresher:
    def __init__(self, domain: Optional[str] = None, client_id: Optional[str] = None, client_secret: Optional[str] = None):
        self.domain = domain or os.environ.get("AUTH0_DOMAIN")
        self.client_id = client_id or os.environ.get("AUTH0_CLIENT_ID")
        self.client_secret = client_secret or os.environ.get("AUTH0_CLIENT_SECRET")
        if not self.domain or not self.client_id or not self.client_secret:
            raise ValueError("AUTH0_DOMAIN, AUTH0_CLIENT_ID, and AUTH0_CLIENT_SECRET are required")
        self.token_url = f"https://{self.domain}/oauth/token"

    def refresh_access_token(self, refresh_token: str) -> Dict[str, Any]:
        payload = {
            "grant_type": "refresh_token",
            "client_id": self.client_id,
            "client_secret": self.client_secret,
            "refresh_token": refresh_token,
        }
        headers = {"Content-Type": "application/json"}
        response = requests.post(self.token_url, json=payload, headers=headers, timeout=30)
        response.raise_for_status()
        data = response.json()
        if "access_token" not in data:
            raise RuntimeError("Auth0 refresh response did not contain an access_token")
        return data


def refresh_expired_session(refresh_token: str, domain: Optional[str] = None, client_id: Optional[str] = None, client_secret: Optional[str] = None) -> Dict[str, Any]:
    refresher = Auth0TokenRefresher(domain=domain, client_id=client_id, client_secret=client_secret)
    return refresher.refresh_access_token(refresh_token)
